-- case: boxplot_grouped
SELECT * FROM (SELECT * FROM box_data) AS __schema__ LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "grp" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") SELECT MIN("grp") AS "grp", MIN("value") AS "value" FROM "__ggsql_source__" UNION ALL SELECT MAX("grp") AS "grp", MAX("value") AS "value" FROM "__ggsql_source__";
SELECT *, "__ggsql_stat_type" AS "__ggsql_aes_type__", "__ggsql_stat_value" AS "__ggsql_aes_pos2__", "__ggsql_stat_value2" AS "__ggsql_aes_pos2end__" FROM (WITH summary AS ( SELECT *, (CASE WHEN (q1 - 1.5 * (q3 - q1)) >= (min) THEN (q1 - 1.5 * (q3 - q1)) ELSE (min) END) AS lower, (CASE WHEN (q3 + 1.5 * (q3 - q1)) <= (max) THEN (q3 + 1.5 * (q3 - q1)) ELSE (max) END) AS upper FROM ( SELECT "__ggsql_aes_pos1__", MIN("__ggsql_aes_pos2__") AS min, MAX("__ggsql_aes_pos2__") AS max, (SELECT (MAX(CASE WHEN __tile = 1 THEN __val END) + MIN(CASE WHEN __tile = 2 THEN __val END)) / 2.0 FROM (SELECT "__ggsql_aes_pos2__" AS __val, NTILE(4) OVER (PARTITION BY "__ggsql_aes_pos1__" ORDER BY "__ggsql_aes_pos2__") AS __tile, "__ggsql_aes_pos1__" FROM (SELECT *, "grp" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos2__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_pos1__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_pos1__")) AS q1, (SELECT (MAX(CASE WHEN __tile = 2 THEN __val END) + MIN(CASE WHEN __tile = 3 THEN __val END)) / 2.0 FROM (SELECT "__ggsql_aes_pos2__" AS __val, NTILE(4) OVER (PARTITION BY "__ggsql_aes_pos1__" ORDER BY "__ggsql_aes_pos2__") AS __tile, "__ggsql_aes_pos1__" FROM (SELECT *, "grp" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos2__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_pos1__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_pos1__")) AS median, (SELECT (MAX(CASE WHEN __tile = 3 THEN __val END) + MIN(CASE WHEN __tile = 4 THEN __val END)) / 2.0 FROM (SELECT "__ggsql_aes_pos2__" AS __val, NTILE(4) OVER (PARTITION BY "__ggsql_aes_pos1__" ORDER BY "__ggsql_aes_pos2__") AS __tile, "__ggsql_aes_pos1__" FROM (SELECT *, "grp" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos2__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_pos1__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_pos1__")) AS q3 FROM (SELECT *, "grp" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") AS "__ggsql_qt__" WHERE "__ggsql_aes_pos2__" IS NOT NULL GROUP BY "__ggsql_aes_pos1__" ) AS "__ggsql_fn__" ), outliers AS ( SELECT raw."__ggsql_aes_pos2__" AS value, 'outlier' AS type, raw."__ggsql_aes_pos1__" AS "__ggsql_aes_pos1__" FROM (SELECT *, "grp" AS "__ggsql_aes_pos1__", "value" AS "__ggsql_aes_pos2__" FROM (SELECT * FROM box_data) AS "__ggsql_src__") raw JOIN summary ON raw."__ggsql_aes_pos1__" = summary."__ggsql_aes_pos1__" WHERE raw."__ggsql_aes_pos2__" NOT BETWEEN summary.lower AND summary.upper ) SELECT "__ggsql_aes_pos1__", 'lower_whisker' AS "__ggsql_stat_type", q1 AS "__ggsql_stat_value", lower AS "__ggsql_stat_value2" FROM summary UNION ALL SELECT "__ggsql_aes_pos1__", 'upper_whisker' AS "__ggsql_stat_type", q3 AS "__ggsql_stat_value", upper AS "__ggsql_stat_value2" FROM summary UNION ALL SELECT "__ggsql_aes_pos1__", 'box' AS "__ggsql_stat_type", q1 AS "__ggsql_stat_value", q3 AS "__ggsql_stat_value2" FROM summary UNION ALL SELECT "__ggsql_aes_pos1__", 'median' AS "__ggsql_stat_type", median AS "__ggsql_stat_value", NULL AS "__ggsql_stat_value2" FROM summary UNION ALL SELECT "__ggsql_aes_pos1__", type AS "__ggsql_stat_type", value AS "__ggsql_stat_value", NULL AS "__ggsql_stat_value2" FROM outliers ) AS "__ggsql_stat__";

-- case: density_grouped
SELECT * FROM (SELECT * FROM dens_data) AS __schema__ LIMIT 1;
WITH "__ggsql_source__" AS (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") SELECT MIN("value") AS "value", MIN("grp") AS "grp" FROM "__ggsql_source__" UNION ALL SELECT MAX("value") AS "value", MAX("grp") AS "grp" FROM "__ggsql_source__";
SELECT *, "__ggsql_stat_pos1" AS "__ggsql_aes_pos1__", "__ggsql_stat_density" AS "__ggsql_aes_pos2__" FROM (WITH RECURSIVE bandwidth AS ( SELECT 0.9 * (CASE WHEN (SQRT(AVG("__ggsql_aes_pos1__"*"__ggsql_aes_pos1__") - AVG("__ggsql_aes_pos1__")*AVG("__ggsql_aes_pos1__"))) <= (((SELECT (MAX(CASE WHEN __tile = 3 THEN __val END) + MIN(CASE WHEN __tile = 4 THEN __val END)) / 2.0 FROM (SELECT "__ggsql_aes_pos1__" AS __val, NTILE(4) OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ORDER BY "__ggsql_aes_pos1__") AS __tile, "__ggsql_aes_fill__", "__ggsql_aes_stroke__" FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos1__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_fill__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_fill__") AND ("__ggsql_tile__"."__ggsql_aes_stroke__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_stroke__")) - (SELECT (MAX(CASE WHEN __tile = 1 THEN __val END) + MIN(CASE WHEN __tile = 2 THEN __val END)) / 2.0 FROM (SELECT "__ggsql_aes_pos1__" AS __val, NTILE(4) OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ORDER BY "__ggsql_aes_pos1__") AS __tile, "__ggsql_aes_fill__", "__ggsql_aes_stroke__" FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos1__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_fill__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_fill__") AND ("__ggsql_tile__"."__ggsql_aes_stroke__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_stroke__"))) / 1.34) THEN (SQRT(AVG("__ggsql_aes_pos1__"*"__ggsql_aes_pos1__") - AVG("__ggsql_aes_pos1__")*AVG("__ggsql_aes_pos1__"))) ELSE (((SELECT (MAX(CASE WHEN __tile = 3 THEN __val END) + MIN(CASE WHEN __tile = 4 THEN __val END)) / 2.0 FROM (SELECT "__ggsql_aes_pos1__" AS __val, NTILE(4) OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ORDER BY "__ggsql_aes_pos1__") AS __tile, "__ggsql_aes_fill__", "__ggsql_aes_stroke__" FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos1__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_fill__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_fill__") AND ("__ggsql_tile__"."__ggsql_aes_stroke__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_stroke__")) - (SELECT (MAX(CASE WHEN __tile = 1 THEN __val END) + MIN(CASE WHEN __tile = 2 THEN __val END)) / 2.0 FROM (SELECT "__ggsql_aes_pos1__" AS __val, NTILE(4) OVER (PARTITION BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ORDER BY "__ggsql_aes_pos1__") AS __tile, "__ggsql_aes_fill__", "__ggsql_aes_stroke__" FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_pct__" WHERE "__ggsql_aes_pos1__" IS NOT NULL) AS "__ggsql_tile__" WHERE ("__ggsql_tile__"."__ggsql_aes_fill__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_fill__") AND ("__ggsql_tile__"."__ggsql_aes_stroke__" IS NOT DISTINCT FROM "__ggsql_qt__"."__ggsql_aes_stroke__"))) / 1.34) END) * POWER(1.0 * COUNT(*), -0.2) AS bw, "__ggsql_aes_fill__", "__ggsql_aes_stroke__", MIN("__ggsql_aes_pos1__") AS x_min, MAX("__ggsql_aes_pos1__") AS x_max FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_qt__" WHERE "__ggsql_aes_pos1__" IS NOT NULL GROUP BY "__ggsql_aes_fill__", "__ggsql_aes_stroke__" ), data AS ( SELECT "__ggsql_aes_fill__", "__ggsql_aes_stroke__", "__ggsql_aes_pos1__" AS val, 1.0 AS weight FROM (SELECT *, "grp" AS "__ggsql_aes_fill__", "value" AS "__ggsql_aes_pos1__", "grp" AS "__ggsql_aes_stroke__" FROM (SELECT * FROM dens_data) AS "__ggsql_src__") AS "__ggsql_data__" WHERE "__ggsql_aes_pos1__" IS NOT NULL ), "__ggsql_base__"(n) AS (SELECT 0 UNION ALL SELECT n + 1 FROM "__ggsql_base__" WHERE n < 7),"__ggsql_seq__"(n) AS (SELECT CAST(a.n * 64 + b.n * 8 + c.n AS REAL) AS n FROM "__ggsql_base__" a, "__ggsql_base__" b, "__ggsql_base__" c WHERE a.n * 64 + b.n * 8 + c.n < 512), global_range AS ( SELECT MIN(x_min) AS min, MAX(x_max) AS max, 3 * MAX(bw) AS expansion FROM bandwidth ), grid AS ( SELECT "__ggsql_aes_fill__", "__ggsql_aes_stroke__", ("__ggsql_global__".min - "__ggsql_global__".expansion) + (seq.n * (("__ggsql_global__".max - "__ggsql_global__".min) + 2 * "__ggsql_global__".expansion) / 511) AS x FROM global_range AS "__ggsql_global__" CROSS JOIN "__ggsql_seq__" AS seq CROSS JOIN (SELECT DISTINCT "__ggsql_aes_fill__", "__ggsql_aes_stroke__" FROM bandwidth) AS "__ggsql_groups__" ) SELECT "__ggsql_stat_pos1", "__ggsql_aes_fill__", "__ggsql_aes_stroke__", "__ggsql_stat_intensity", "__ggsql_stat_intensity" / "__norm" AS "__ggsql_stat_density" FROM ( SELECT grid.x AS "__ggsql_stat_pos1", grid."__ggsql_aes_fill__" AS "__ggsql_aes_fill__", grid."__ggsql_aes_stroke__" AS "__ggsql_aes_stroke__", SUM(data.weight * ((EXP(-0.5 * (grid.x - data.val) * (grid.x - data.val) / (bandwidth.bw * bandwidth.bw))) * 0.3989422804014327)) / MIN(bandwidth.bw) AS "__ggsql_stat_intensity", SUM(data.weight) AS "__norm" FROM data INNER JOIN bandwidth ON (data."__ggsql_aes_fill__" IS NOT DISTINCT FROM bandwidth."__ggsql_aes_fill__") AND (data."__ggsql_aes_stroke__" IS NOT DISTINCT FROM bandwidth."__ggsql_aes_stroke__") INNER JOIN grid ON (grid."__ggsql_aes_fill__" IS NOT DISTINCT FROM data."__ggsql_aes_fill__") AND (grid."__ggsql_aes_stroke__" IS NOT DISTINCT FROM data."__ggsql_aes_stroke__") GROUP BY grid.x, grid."__ggsql_aes_fill__", grid."__ggsql_aes_stroke__" ORDER BY grid.x, grid."__ggsql_aes_fill__", grid."__ggsql_aes_stroke__" ) AS "__ggsql_kde__") AS "__ggsql_stat__";

